// 녹음 봇이 보낸 manifest를 확인한다. 회의 ID, 파일 이름, 서버·채널 ID는 파일 경로와 Discord 요청에 들어가므로 형식이 맞는 것만 받는다.
// 틀리면 실행을 실패시켜 조용히 끝나지 않게 한다. 오류 메시지에는 값을 넣지 않는다(참석자 ID가 실행 기록에 남지 않게).
const manifest = $input.first().json.body;
const errors = [];
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isMs = (value) => Number.isFinite(value) && value >= 0;

if (!isObject(manifest)) throw new Error('manifest가 JSON 객체가 아닙니다');
if (!/^\d{8}-\d{4}$/.test(manifest.meetingId ?? '')) errors.push('meetingId 형식이 다릅니다');
if (!/^\d{17,20}$/.test(manifest.guildId ?? '')) errors.push('guildId 형식이 다릅니다');
if (!/^\d{17,20}$/.test(manifest.textChannelId ?? '')) errors.push('textChannelId 형식이 다릅니다');
for (const key of ['startedAt', 'endedAt']) {
  if (typeof manifest[key] !== 'string' || Number.isNaN(Date.parse(manifest[key]))) errors.push(`${key}가 시각이 아닙니다`);
}

const participants = Array.isArray(manifest.participants) ? manifest.participants : [];
if (!Array.isArray(manifest.participants)) errors.push('participants가 배열이 아닙니다');

const segments = Array.isArray(manifest.segments) ? manifest.segments : [];
if (!Array.isArray(manifest.segments)) errors.push('segments가 배열이 아닙니다');
else if (segments.length === 0) errors.push('녹음된 발화가 없습니다');
const files = new Set();
segments.forEach((s, i) => {
  if (!/^\d{9}-\d+\.webm$/.test(s?.file ?? '')) errors.push(`segments[${i}].file 형식이 다릅니다`);
  else if (files.has(s.file)) errors.push(`segments[${i}].file이 중복됩니다`);
  else files.add(s.file);
  if (!isMs(s?.startMs) || !isMs(s?.endMs) || s.endMs < s.startMs) errors.push(`segments[${i}] 시각이 잘못됐습니다`);
});

const gaps = manifest.gaps ?? [];
if (!Array.isArray(gaps)) errors.push('gaps가 배열이 아닙니다');
else gaps.forEach((g, i) => {
  if (!isMs(g?.startMs) || (g.endMs !== undefined && (!isMs(g.endMs) || g.endMs < g.startMs))) {
    errors.push(`gaps[${i}] 시각이 잘못됐습니다`);
  }
});

if (errors.length > 0) throw new Error(`manifest를 처리할 수 없습니다: ${errors.join(', ')}`);

// 녹음 봇은 서버 멤버 정보를 못 읽으면 표시 이름 자리에 Discord ID를 넣는다.
// ID가 녹취와 OpenAI 프롬프트에 들어가지 않게 "참석자 N"으로 바꾼다.
const names = new Map();
const nameOf = (userId, displayName) => {
  if (names.has(userId)) return names.get(userId);
  const usable = typeof displayName === 'string' && displayName.trim() !== '' && !/^\d{17,20}$/.test(displayName.trim());
  const name = usable ? displayName.trim() : `참석자 ${names.size + 1}`;
  names.set(userId, name);
  return name;
};
participants.forEach((p) => nameOf(p?.userId, p?.displayName));

return [{
  json: {
    meetingId: manifest.meetingId,
    guildId: manifest.guildId,
    textChannelId: manifest.textChannelId,
    startedAt: manifest.startedAt,
    endedAt: manifest.endedAt,
    // 참석자 이름을 알려 주면 음성 인식이 이름을 덜 틀린다.
    prompt: names.size > 0 ? `참석자: ${[...new Set(names.values())].join(', ')}` : '',
    segments: segments.map((s) => ({
      file: s.file,
      startMs: s.startMs,
      endMs: s.endMs,
      speaker: nameOf(s.userId, s.displayName),
    })),
    gaps: gaps.map((g) => ({ startMs: g.startMs, endMs: g.endMs ?? null, reason: typeof g.reason === 'string' ? g.reason : '' })),
  },
}];

// 발화마다 항목 하나를 만들어 파일 읽기 노드에 넘긴다. 파일 이름은 앞 노드에서 형식을 확인했다.
const { meetingId, segments } = $('녹음 정보 확인').first().json;
return segments.map((segment) => ({
  json: { file: segment.file, path: `/recordings/${meetingId}/segments/${segment.file}` },
}));

// 파일 읽기 노드는 경로를 glob으로 찾아서, 파일이 없으면 오류 없이 항목 0개를 낸다(n8n 2.42.6에서 확인).
// 그대로 두면 워크플로가 조용히 성공으로 끝나므로 읽은 파일이 발화 목록과 하나라도 다르면 실패시킨다.
const expected = $('발화 목록').all().map((item) => item.json.file);
const files = $input.all().filter((item) => item.binary?.data);
if (files.length !== expected.length) {
  throw new Error(`발화 파일 ${expected.length}개 중 ${files.length}개만 읽었습니다. 녹음 폴더를 확인해 주세요`);
}
// 음성 인식 결과를 발화 순서로 맞추므로 읽은 순서도 같아야 한다.
const misplaced = files.findIndex((item, i) => item.binary.data.fileName !== expected[i]);
if (misplaced !== -1) throw new Error(`${misplaced + 1}번째 발화 파일이 발화 목록과 다릅니다`);
return files;

// 음성 인식 결과를 회의 시작 기준 시각 순 녹취로 합친다. 이 [HH:MM:SS] 문자열이 이후 단계에서 녹취 근거의 식별자가 된다.
// 녹취 원문은 이 노드 출력(n8n 실행 기록, 7일 보관)에만 남기고 Discord에는 발화 수만 알린다.
const meeting = $('녹음 정보 확인').first().json;
const texts = $input.all().map((item) => item.json.text);
if (texts.length !== meeting.segments.length) {
  throw new Error(`음성 인식 결과 수(${texts.length})가 발화 수(${meeting.segments.length})와 다릅니다`);
}

const pad = (n) => String(n).padStart(2, '0');
const clock = (ms) => {
  const s = Math.floor(ms / 1000);
  return `${pad(Math.floor(s / 3600))}:${pad(Math.floor(s / 60) % 60)}:${pad(s % 60)}`;
};

const lines = [];
let empty = 0;
meeting.segments.forEach((segment, i) => {
  const text = typeof texts[i] === 'string' ? texts[i].replace(/\s+/g, ' ').trim() : '';
  if (text === '') {
    empty += 1;
    return;
  }
  lines.push({ ms: segment.startMs, order: 1, text: `[${clock(segment.startMs)}] ${segment.speaker}: ${text}` });
});
// 녹음이 끊긴 구간도 시각 순으로 끼워 넣는다. 그 사이의 말은 녹음되지 않았다.
for (const gap of meeting.gaps) {
  const length = gap.endMs === null ? '회의 끝까지' : `약 ${Math.round((gap.endMs - gap.startMs) / 1000)}초`;
  const reason = gap.reason ? `, ${gap.reason}` : '';
  lines.push({ ms: gap.startMs, order: 0, text: `[${clock(gap.startMs)}] (녹음 끊김 ${length}${reason})` });
}
lines.sort((a, b) => a.ms - b.ms || a.order - b.order);

const segmentCount = meeting.segments.length;
return [{
  json: {
    meetingId: meeting.meetingId,
    guildId: meeting.guildId,
    textChannelId: meeting.textChannelId,
    transcript: lines.map((line) => line.text).join('\n'),
    segmentCount,
    emptyCount: empty,
    notice: `회의 ${meeting.meetingId} 녹취 완료, 발화 ${segmentCount}개`,
  },
}];
